  function idx(){return Math.min(n-1,Math.round(g.scrollLeft/w()));}
  function upd(){c.textContent=(idx()+1)+' of '+n;bt[0].disabled=g.scrollLeft<4;bt[1].disabled=g.scrollLeft+g.clientWidth>=g.scrollWidth-4;}
  function go(d){g.scrollTo({left:(idx()+d)*w(),behavior:'smooth'});}
